// ---------- Gerador de links (página /link do painel, para a Gabrielle) ----------
// Recebe qualquer link de produto da Shopee e devolve o link de afiliado da conta, com subId "gabi".
async function geradorLink(k: string, url: string) {
  const { data: c } = await db.from("config").select("valor").eq("chave", "gerador_convite").maybeSingle();
  if (!c?.valor || k !== c.valor) return { erro: "Acesso inválido. Use o link que o Julio te mandou." };
  url = (url ?? "").trim().match(/https?:\/\/\S+/)?.[0] ?? "";
  let host = "";
  try { host = new URL(url).hostname; } catch { /* inválido */ }
  if (!/(^|\.)(shopee\.com\.br|shp\.ee)$/.test(host)) return { erro: "Cole um link de produto da Shopee (shopee.com.br ou shp.ee)." };
  // descobre loja/produto (links curtos redirecionam para a página do produto)
  let longo = url;
  for (let i = 0; i < 3 && !/i\.\d+\.\d+|\/product\/\d+\/\d+/.test(longo); i++) {
    try {
      const r = await fetch(longo, { redirect: "manual", headers: { "User-Agent": "Mozilla/5.0" } });
      const loc = r.headers.get("location");
      if (!loc) break;
      longo = new URL(loc, longo).toString();
    } catch { break; }
  }
  const ids = longo.match(/i\.(\d+)\.(\d+)/) ?? longo.match(/\/product\/(\d+)\/(\d+)/);
  let produto: Record<string, unknown> | null = null;
  if (ids) {
    try {
      const d = await shopee(`{productOfferV2(shopId:${ids[1]},itemId:${ids[2]},limit:1){nodes{productName imageUrl priceMin commissionRate sales ratingStar}}}`);
      const n = d?.productOfferV2?.nodes?.[0];
      if (n) produto = { nome: n.productName, imagem: n.imageUrl, preco: Number(n.priceMin), comissao: Number(n.commissionRate), vendas: n.sales, nota: n.ratingStar };
    } catch (e) { console.error("gerador produto", String(e).slice(0, 200)); }
  }
  const origem = ids ? `https://shopee.com.br/product/${ids[1]}/${ids[2]}` : url;
  const d = await shopee(`mutation{generateShortLink(input:{originUrl:${JSON.stringify(origem)},subIds:["gabi","gerador"]}){shortLink}}`);
  const link = d?.generateShortLink?.shortLink;
  if (!link) return { erro: "A Shopee não devolveu o link. Confira se é um link de produto." };
  await db.from("links_gerador").insert({ url_original: url, link, nome: (produto?.nome as string) ?? null, imagem: (produto?.imagem as string) ?? null, preco: (produto?.preco as number) ?? null });
  return { ok: true, link, produto };
}

async function geradorHistorico(k: string) {
  const { data: c } = await db.from("config").select("valor").eq("chave", "gerador_convite").maybeSingle();
  if (!c?.valor || k !== c.valor) return { erro: "Acesso inválido." };
  const { data } = await db.from("links_gerador").select("link,nome,imagem,preco,criado_em").order("criado_em", { ascending: false }).limit(15);
  return { ok: true, links: data ?? [] };
}

